		// Now count n in [1, x] such that n ≡ s (mod M).
		// n = s + t*M, t >= 0.
		// s + t*M <= x => t <= (x - s) / M.
		// If x < s, count = 0.
		// Else count = (x - s) / M + 1.
		if x >= s {
			count += (x - s) / M + 1
		}
	}

	fmt.Println(count)
}
