package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
	"strconv"
	"strings"
)

func modPow(base, exp, mod int64) int64 {
	base %= mod
	if base < 0 {
		base += mod
	}
	result := int64(1)
	for exp > 0 {
		if exp%2 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp /= 2
	}
	return result
}

func modInverse(a, mod int64) int64 {
	// Since mod is prime, use Fermat's little theorem: a^(mod-2) mod mod
	return modPow(a, mod-2, mod)
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	line, _ := reader.ReadString('\n')
	parts := strings.Fields(line)
	if len(parts) < 4 {
		return
	}
	a, _ := strconv.ParseInt(parts[0], 10, 64)
	b, _ := strconv.ParseInt(parts[1], 10, 64)
	p, _ := strconv.ParseInt(parts[2], 10, 64)
	x, _ := strconv.ParseInt(parts[3], 10, 64)

	// We need to count n in [1, x] such that n * a^n ≡ b (mod p)
	// This is equivalent to n ≡ b * (a^n)^(-1) (mod p)
	// i.e., n ≡ b * a^(-n) (mod p)
	// i.e., n ≡ b * (a^(-1))^n (mod p)
	// Let inv_a = a^(-1) mod p
	// Then n ≡ b * (inv_a)^n (mod p)

	// The function f(n) = b * (inv_a)^n mod p is periodic with period ord_p(inv_a)
	// where ord_p(inv_a) is the multiplicative order of inv_a modulo p.
	// Also n mod p is periodic with period p.
	// So the condition n ≡ b * (inv_a)^n (mod p) is periodic with period lcm(p, ord_p(inv_a)).
	// But ord_p(inv_a) divides p-1 (by Fermat's little theorem, since a is in [1, p-1]).
	// So the period is lcm(p, d) where d = ord_p(inv_a) divides p-1.
	// Since p is prime and d divides p-1, gcd(p, d) = 1 (because d < p and p is prime, unless d=1).
	// Actually, d divides p-1, so d < p, and since p is prime, gcd(p, d) = 1.
	// Therefore lcm(p, d) = p * d.

	// Let's compute d = ord_p(inv_a).
	// To find the multiplicative order, we factor p-1 and check divisors.

	// First, handle the case where a ≡ 0 mod p, but a < p and a >= 1, so a is not 0 mod p.
	// Also b < p and b >= 1.

	// Compute inv_a
	inv_a := modInverse(a, p)

	// Find the multiplicative order of inv_a modulo p.
	// Factor p-1.
	n_minus_1 := p - 1
	// Factorize n_minus_1
	factors := map[int64]int{}
	temp := n_minus_1
	for i := int64(2); i*i <= temp; i++ {
		for temp%i == 0 {
			factors[i]++
			temp /= i
		}
	}
	if temp > 1 {
		factors[temp]++
	}

	// The order d divides n_minus_1.
	// Start with d = n_minus_1, and try to reduce it by each prime factor.
	d := n_minus_1
	for prime, _ := range factors {
		for d%prime == 0 && modPow(inv_a, d/prime, p) == 1 {
			d /= prime
		}
	}

	// Now the period of the condition is T = p * d.
	// But wait, we need to be careful. The condition is:
	// n ≡ b * (inv_a)^n (mod p)
	// Let's define g(n) = b * (inv_a)^n mod p.
	// g(n) has period d: g(n+d) = b * (inv_a)^(n+d) = b * (inv_a)^n * (inv_a)^d = b * (inv_a)^n * 1 = g(n) (mod p).
	// And n mod p has period p.
	// So the pair (n mod p, g(n)) has period lcm(p, d) = p*d (since gcd(p,d)=1).
	// Therefore, the condition n ≡ g(n) (mod p) is periodic with period T = p*d.

	T := p * d

	// Count the number of n in [1, T] that satisfy the condition.
	// Then the answer is:
	// full_cycles = x / T
	// remainder = x % T
	// answer = full_cycles * count_in_one_period + count_in_first_remainder

	count_in_one_period := int64(0)
	for n := int64(1); n <= T; n++ {
		// Compute g(n) = b * (inv_a)^n mod p
		// (inv_a)^n mod p
		pow_val := modPow(inv_a, n, p)
		gn := b * pow_val % p
		if n%p == gn {
			count_in_one_period++
		}
	}

	full_cycles := x / T
	remainder := x % T

	count_in_first_remainder := int64(0)
	for n := int64(1); n <= remainder; n++ {
		pow_val := modPow(inv_a, n, p)
		gn := b * pow_val % p
		if n%p == gn {
			count_in_first_remainder++
		}
	}

	answer := full_cycles*count_in_one_period + count_in_first_remainder

	fmt.Println(answer)
}
