func modPow(base, exp, mod int64) int64 {
	if mod == 1 {
		return 0
	}
	result := int64(1)
	base = base % mod
	for exp > 0 {
		if exp%2 == 1 {
			result = (result * base) % mod
		}
		exp = exp >> 1
		base = (base * base) % mod
	}
	return result
