	//      So count = max(0, floor((k_max - k0) / p) - m_min + 1).

	// Let's implement this.

	T := p - 1
	count := int64(0)

	// Precompute a^r mod p for r = 0 to T-1? T can be up to 10^6, so it's feasible.
	// But we can compute iteratively.
	ar := int64(1) // a^0 mod p
