						kmax := (x - r) / T
						count += kmax + 1
					}
				}
			}
			// else no solution
		} else {
			// Find k0 = C * A^(-1) mod p
			// Compute modular inverse of A mod p
			// Since p is prime, use Fermat: A^(-1) = A^(p-2) mod p
			Ainv := modPow(A, p-2, p)
			k0 := (C * Ainv) % p

			var lowerBound int64
